import{_ as s,o as a,c as t,a5 as i}from"./chunks/framework.BYXPg_yw.js";const k=JSON.parse('{"title":"휠 제어 — Python 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/python/wheel.md","filePath":"ko/software/sdk/python/wheel.md","lastUpdated":1793350928000}'),n={name:"ko/software/sdk/python/wheel.md"};function o(l,e,h,p,d,r){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="휠-제어-—-python-예제" tabindex="-1">휠 제어 — Python 예제 <a class="header-anchor" href="#휠-제어-—-python-예제" aria-label="Permalink to &quot;휠 제어 — Python 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/python/example/sport/rbq_wheel.py</code></p><p>C++ <a href="/RBQ/nightly/ko/software/sdk/cpp/wheel.html">휠 제어</a>의 Python 포팅입니다. 바퀴 관절의 소유권만 가져온 뒤 <strong>앱 슬롯 21</strong> 로 <code>rt/rbq/ref/motion/_21</code>에 <code>MotionRef_</code>를 발행해 **RBQ 휠 기체(RBQ-W)**의 바퀴 네 개를 돌리고, 끝나면 놓아 줍니다.</p><h2 id="동작-방식" tabindex="-1">동작 방식 <a class="header-anchor" href="#동작-방식" aria-label="Permalink to &quot;동작 방식&quot;">​</a></h2><ol><li>명령행에서 <code>interface</code>와 선택 인자 <code>torque kd seconds</code>를 읽습니다.</li><li><code>ChannelFactoryInitialize(0, interface)</code> 호출 후 <code>ChannelPublisher(&quot;rt/rbq/ref/motion/_21&quot;, MotionRef_)</code>, <code>ChannelPublisher(&quot;rt/rbq/cmd/motion/owner/_21&quot;, JointOwnershipCmd_)</code>와, 로봇이 적용하는 레퍼런스를 받는 <code>ChannelSubscriber(&quot;rt/rbq/ref/motion/_0&quot;, MotionRef_)</code>를 만듭니다.</li><li>DDS 디스커버리를 ~0.5 초 기다린 뒤 토크 0 레퍼런스를 먼저 보내고, <code>whl_joint = [True] * 4</code>인 <code>JointOwnershipCmd_</code>를 보냅니다.</li><li><code>whl_joint</code>를 500 Hz 로 발행합니다 — <code>kp = 0</code>, 주어진 <code>kd</code>, 0.5 초 동안 0 에서 올라가는 토크. 0.5 초마다 적용된 바퀴 레퍼런스를 출력합니다.</li><li>시간이 끝나면(또는 Ctrl+C) 토크를 0 으로 0.5 초 보낸 뒤 <code>kp = kd = torque = 0</code>을 보내고 종료합니다.</li></ol><p>떠 있는 바퀴는 <strong>속도 = torque / kd</strong> [rad/s]에 수렴합니다. 게인은 CAN FD 기체든 일반 CAN 기체든 물리값으로 보내고, Network 가 보드에 맞게 바꿉니다. 슬롯 20 을 쓰는 <a href="/RBQ/nightly/ko/software/sdk/python/low-level.html">Low Level (Python)</a>과 함께 돌릴 수 있습니다.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>바닥에 있으면 바퀴가 도는 동안 로봇이 <strong>굴러갑니다</strong>. 공간을 확보하고, 작은 토크부터 시작하고, 원격 비상정지를 손에 두세요.</p></div><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li><code>rbq_sdk_py</code> import 가능 — <a href="/RBQ/nightly/ko/software/sdk/python/overview.html">Python SDK 개요</a> 참조.</li><li>로봇 스택이 실행 중이며 동일 DDS 인터페이스 사용.</li><li><strong>서 있는 RBQ 휠 기체(RBQ-W).</strong> 시뮬레이터에서는 Motion 과 MuJoCo 를 <code>--wheel</code>로 띄웁니다(<code>bash scripts/sim.bash --robot wheel</code>).</li></ul><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RBQ/rbq_sdk/python/example/sport</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_wheel.py</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [networkInterface] [torque] [kd] [seconds]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 앞으로 2 rad/s, 3 초(기본값) — 인터페이스가 항상 먼저 옵니다:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_wheel.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 뒤로 1 rad/s, 5 초:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rbq_wheel.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eth0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -0.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre></div><p>인자는 모두 위치 인자이므로 <strong>인터페이스를 첫 인자로 넘겨야 합니다</strong>.</p><p>인자·기본값과 예제가 끝난 뒤의 동작은 <a href="/RBQ/nightly/ko/software/sdk/cpp/wheel.html#run">C++ 버전</a>과 같습니다. 로봇에 닿는 인터페이스를 쓰세요 — 로봇 PC 에서 돌리면 <code>lo</code>, 다른 호스트에서는 본인 NIC.</p><h2 id="출력-예시" tabindex="-1">출력 예시 <a class="header-anchor" href="#출력-예시" aria-label="Permalink to &quot;출력 예시&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[rbq_wheel] wheel ownership requested (app 21)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=0.00 kd=0.500) HLW(tq=0.00 kd=0.500) FRW(tq=0.00 kd=0.500) FLW(tq=0.00 kd=0.500)</span></span>
<span class="line"><span>[rbq_wheel] applied: HRW(tq=1.00 kd=0.500) HLW(tq=1.00 kd=0.500) FRW(tq=1.00 kd=0.500) FLW(tq=1.00 kd=0.500)</span></span>
<span class="line"><span>[rbq_wheel] done - wheels released (kp = kd = torque = 0)</span></span></code></pre></div><p>바퀴 순서는 <code>HRW HLW FRW FLW</code>(관절 12–15)입니다. 일반 CAN 기체에서는 <code>kd</code>가 보드 단위로 반올림된 값(예: <code>0.501</code>)으로 보입니다.</p>`,16)])])}const u=s(n,[["render",o]]);export{k as __pageData,u as default};
